// Keep closer recognition options available on every level without changing
// which evidence keys the answer; advanced levels retain all three alternatives.
for(const f of nursingFacts.filter(f=>f.topic==="GI"&&f.subsectionId==="recognition")) {
  const item=giCases[f.id];if(item.harderFoils)item.foils=[...item.harderFoils];
}

// Each replacement is written for this case's question and clinical evidence.
// Keep Easy alternatives distinct while avoiding unrelated body-system trivia.
function clinicalFoils(id:string, alternatives:[string,string][]) {
  if(!giCases[id]||alternatives.length!==3)throw new Error(`Invalid GI foil repair ${id}`);
  giCases[id].foils=alternatives.map(([text,why])=>({text,why}));
}
